"use client";

import React from "react";
import { Accordion as AccordionRadix } from "radix-ui";
import { ChevronDownIcon } from "@radix-ui/react-icons";

import { cn } from "@/lib/utils";

function Accordion({
  ...props
}: React.ComponentProps<typeof AccordionRadix.Root>) {
  return <AccordionRadix.Root data-slot="accordion" {...props} />;
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Item>) {
  return (
    <AccordionRadix.Item
      data-slot="accordion-item"
      className={cn("overflow-hidden", className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Trigger>) {
  return (
    <AccordionRadix.Header className="flex">
      <AccordionRadix.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "group flex justify-between flex-1 cursor-pointer items-center gap-1 p-1 w-full h6 hover:bg-gray3 border border-b-1 border-gray-3 border-x-0 border-t-0 px-2",
          className
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon className="group-data-[state=open]:rotate-180 transition duration-300" />
      </AccordionRadix.Trigger>
    </AccordionRadix.Header>
  );
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionRadix.Content>) {
  return (
    <AccordionRadix.Content
      data-slot="accordion-content"
      className="bg-gray-2 data-[state=open]:animate-accordion-open data-[state=closed]:animate-accordion-closed"
      {...props}
    >
      <div className={cn("px-2 py-1", className)}>{children}</div>
    </AccordionRadix.Content>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

@theme animatons {
    --animate-accordion-open: slideDownAccordion 250ms ease-in-out;
    --animate-accordion-closed: slideUpAccordion 250ms ease-in-out;
  }
  @layer components {
    @keyframes slideDownAccordion {
      from {
        height: 0;
      }
      to {
        height: var(--radix-accordion-content-height);
      }
    }

    @keyframes slideUpAccordion {
      from {
        height: var(--radix-accordion-content-height);
      }
      to {
        height: 0;
      }
    }
  }

  --animate-overlay-show: overlayShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-content-show: contentShow 150ms cubic-bezier(0.16, 1, 0.3, 1);

  @keyframes overlayShow {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes contentShow {
    from {
      opacity: 0;
      transform: scale(0.96);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }
